#include <iostream>
#include <new>
struct Point2w {
  int x, y;
  Point2w(int a, int b) : x(a), y(b) { std::cout << "Point2w constructed at: " << this << std::endl; }
  ~Point2w() { std::cout << "Point2w destructed at: " << this << std::endl; }
};
int main() {
  char arena[sizeof(Point2w)]; // Allocate memory on the stack
  Point2w* ptw = new (arena) Point2w(10, 20); // Placement new
  std::cout << "ptw address: " << ptw << std::endl;
  ptw->~Point2w(); // Explicitly call the destructor before arena goes out of scope.
  return 0;
}
